CREATE TABLE "sync_runs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "status" character varying NOT NULL, "revision" character varying NOT NULL DEFAULT '', "error" character varying NOT NULL DEFAULT '', "started_at" timestamptz NOT NULL, "finished_at" timestamptz NOT NULL, "project_sync_runs" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "sync_runs_projects_sync_runs" FOREIGN KEY ("project_sync_runs") REFERENCES "projects" ("id") ON DELETE NO ACTION);
CREATE INDEX "syncrun_started_at_project_sync_runs" ON "sync_runs" ("started_at", "project_sync_runs");
